using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Aster {
static class DailyArt {
 public static readonly string[] Names={"Aster star","Orbit","Crescent","Sunrise","Bloom","Comet","Constellation"};
 public static int Wrap(int n){return ((n%Names.Length)+Names.Length)%Names.Length;}
 public static DateTime Day(DateTimeOffset utc,bool riyadh){return riyadh?utc.ToOffset(TimeSpan.FromHours(3)).Date:TimeZoneInfo.ConvertTime(utc,TimeZoneInfo.Local).Date;}
 public static int Index(DateTime date,bool daily,int choice,int shift){return daily?Wrap((int)(date.Date-new DateTime(2000,1,1)).TotalDays+Wrap(shift)):Wrap(choice);}
 public static int ShiftFor(DateTime date,int desired){return Wrap(desired-(int)(date.Date-new DateTime(2000,1,1)).TotalDays);}
 public static Bitmap Render(int size,int choice){choice=Wrap(choice);if(choice==0)return (Bitmap)SuiteArt.Badge(size);var image=new Bitmap(size,size);Color[] colors={Color.Aqua,Color.FromArgb(165,145,255),Color.FromArgb(137,197,255),Color.FromArgb(255,181,109),Color.FromArgb(255,155,203),Color.FromArgb(106,227,204),Color.FromArgb(163,190,255)};Color accent=colors[choice];using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/128f,size/128f);g.Clear(Color.Transparent);using(var path=PlayColors.Round(new RectangleF(4,4,120,120),20)){using(var b=new LinearGradientBrush(new Point(0,0),new Point(128,128),Color.FromArgb(36,49,76),Color.FromArgb(15,24,40)))g.FillPath(b,path);using(var p=new Pen(Color.FromArgb(110,accent),2))g.DrawPath(p,path);}using(var b=new SolidBrush(accent))using(var pale=new SolidBrush(Color.FromArgb(235,245,255)))using(var pen=new Pen(accent,4)){
 if(choice==1){g.FillEllipse(b,43,43,42,42);g.TranslateTransform(64,64);g.RotateTransform(-25);g.DrawEllipse(pen,-48,-17,96,34);g.ResetTransform();g.ScaleTransform(size/128f,size/128f);g.FillEllipse(pale,91,26,7,7);}
 else if(choice==2){g.FillEllipse(b,28,24,70,78);using(var dark=new SolidBrush(Color.FromArgb(24,35,55)))g.FillEllipse(dark,50,16,64,70);g.FillPolygon(pale,new[]{new Point(95,77),new Point(99,87),new Point(110,91),new Point(99,95),new Point(95,106),new Point(91,95),new Point(81,91),new Point(91,87)});}
 else if(choice==3){g.FillEllipse(b,40,39,48,48);using(var dark=new SolidBrush(Color.FromArgb(22,31,48)))g.FillRectangle(dark,20,69,88,39);g.DrawLine(pen,22,72,106,72);g.DrawLine(pen,35,85,93,85);g.DrawLine(pen,47,98,81,98);for(int i=0;i<5;i++){double a=(i*35+20)*Math.PI/180;g.DrawLine(pen,64+(float)Math.Cos(a)*33,63-(float)Math.Sin(a)*33,64+(float)Math.Cos(a)*45,63-(float)Math.Sin(a)*45);}}
 else if(choice==4){for(int i=0;i<6;i++){g.TranslateTransform(64,64);g.RotateTransform(i*60);g.FillEllipse(b,-12,-43,24,44);g.ResetTransform();g.ScaleTransform(size/128f,size/128f);}g.FillEllipse(pale,51,51,26,26);}
 else if(choice==5){g.FillPolygon(b,new[]{new Point(22,24),new Point(95,55),new Point(72,87)});g.FillEllipse(b,57,52,43,43);g.DrawLine(pen,21,47,44,68);g.DrawLine(pen,46,21,66,39);g.FillEllipse(pale,70,64,16,16);}
 else {Point[] points={new Point(29,89),new Point(47,41),new Point(80,60),new Point(101,28),new Point(91,96)};g.DrawLines(pen,points);foreach(var p in points)g.FillEllipse(pale,p.X-5,p.Y-5,10,10);g.FillEllipse(b,25,24,4,4);g.FillEllipse(b,55,103,4,4);}
 }}return image;}
 [DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr icon);
 public static Icon MakeIcon(int choice){using(var b=Render(64,choice)){IntPtr handle=b.GetHicon();try{using(var temporary=Icon.FromHandle(handle))return (Icon)temporary.Clone();}finally{DestroyIcon(handle);}}}
}
partial class MainWindow {
 Label dailyLogo,pictureDescription;PictureBox bannerPicture,picturePreview;CheckBox dailyPictureCheck;bool changingPictureControls;int shownPicture=-1;Icon dynamicPictureIcon;
 int CurrentPictureNumber(){return DailyArt.Index(DailyArt.Day(DateTimeOffset.UtcNow,preferences.RiyadhTime),preferences.DailyPicture,preferences.PictureChoice,preferences.PictureShift);}
 static void ReplacePicture(PictureBox box,Image image){if(box==null||box.IsDisposed){image.Dispose();return;}var old=box.Image;box.Image=image;if(old!=null)old.Dispose();}
 void RefreshDailyPicture(){int number=CurrentPictureNumber();if(number!=shownPicture){shownPicture=number;if(dailyLogo!=null&&!dailyLogo.IsDisposed){var old=dailyLogo.Image;dailyLogo.Image=DailyArt.Render(44,number);if(old!=null)old.Dispose();}if(bannerPicture!=null&&!bannerPicture.IsDisposed)ReplacePicture(bannerPicture,DailyArt.Render(66,number));var next=DailyArt.MakeIcon(number);Icon=next;var prior=dynamicPictureIcon;dynamicPictureIcon=next;if(prior!=null)prior.Dispose();}if(picturePreview!=null&&!picturePreview.IsDisposed&&(!Equals(picturePreview.Tag,number))){picturePreview.Tag=number;ReplacePicture(picturePreview,DailyArt.Render(88,number));}if(pictureDescription!=null&&!pictureDescription.IsDisposed)pictureDescription.Text=DailyArt.Names[number]+(preferences.DailyPicture?" · changes at midnight in your greeting time zone":" · fixed picture");}
 void SelectPicture(int number){var date=DailyArt.Day(DateTimeOffset.UtcNow,preferences.RiyadhTime);preferences.PictureChoice=DailyArt.Wrap(number);preferences.PictureShift=DailyArt.ShiftFor(date,number);SavePreferences();RefreshDailyPicture();}
 void AddPicturePreferences(FlowLayoutPanel flow){flow.Controls.Add(new Label{Text="A new look each day",AutoSize=true,Font=new Font("Segoe UI",22,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Seven built-in pictures for the sidebar, welcome banner and running window icon.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,8,0,12)});picturePreview=new PictureBox{Size=new Size(100,100),SizeMode=PictureBoxSizeMode.CenterImage};picturePreview.Disposed+=(s,e)=>{var box=(PictureBox)s;if(box.Image!=null)box.Image.Dispose();};flow.Controls.Add(picturePreview);pictureDescription=new Label{AutoSize=true};flow.Controls.Add(pictureDescription);dailyPictureCheck=new CheckBox{Text="Change my app picture every day",AutoSize=true,Checked=preferences.DailyPicture,Margin=new Padding(0,12,0,10)};dailyPictureCheck.CheckedChanged+=(s,e)=>{if(changingPictureControls)return;int current=CurrentPictureNumber();preferences.DailyPicture=dailyPictureCheck.Checked;SelectPicture(current);};flow.Controls.Add(dailyPictureCheck);var row=new FlowLayoutPanel{Width=680,Height=90,WrapContents=true};for(int i=0;i<DailyArt.Names.Length;i++){int choice=i;var pick=Button(DailyArt.Names[i]);pick.Click+=(s,e)=>SelectPicture(choice);row.Controls.Add(pick);}flow.Controls.Add(row);var actions=new FlowLayoutPanel{Width=680,Height=48};var next=Button("Change now");next.Click+=(s,e)=>SelectPicture(CurrentPictureNumber()+1);actions.Controls.Add(next);var keep=Button("Keep this picture");keep.Click+=(s,e)=>{int current=CurrentPictureNumber();preferences.DailyPicture=false;changingPictureControls=true;dailyPictureCheck.Checked=false;changingPictureControls=false;SelectPicture(current);};actions.Controls.Add(keep);flow.Controls.Add(actions);flow.Controls.Add(new Label{Text="Rotation works offline. If Aster is closed at midnight, it catches up when reopened.\r\nThe executable and desktop-shortcut icons keep their installed design; Windows may\r\nalso keep a cached taskbar icon. No wallpaper or account picture is changed.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,8,0,24)});RefreshDailyPicture();}
}
}

